regoTemplate:
package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.account.active
  input.account.owner
  input.account.last_review_days <= 90
}

deny contains msg if {
  input.account.active
  not input.account.owner
  msg := "{{controlId}}: active account missing owner"
}

deny contains msg if {
  input.account.last_review_days > 90
  msg := "{{controlId}}: access review is stale"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.request.authenticated
  input.request.role_approved
  input.request.action_allowed
}

deny contains msg if {
  not input.request.authenticated
  msg := "{{controlId}}: request is not authenticated"
}

deny contains msg if {
  input.request.authenticated
  not input.request.role_approved
  msg := "{{controlId}}: role is not approved for this resource"
}

deny contains msg if {
  input.request.authenticated
  input.request.role_approved
  not input.request.action_allowed
  msg := "{{controlId}}: action exceeds approved authorization"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.logging.enabled
  input.logging.retention_days >= 180
  input.logging.alerting
}

deny contains msg if {
  not input.logging.enabled
  msg := "{{controlId}}: logging is disabled"
}

deny contains msg if {
  input.logging.retention_days < 180
  msg := "{{controlId}}: log retention is below minimum"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.asset.baseline_id
  input.asset.drift_count == 0
}

allow if {
  input.asset.baseline_id
  input.asset.approved_exception
}

deny contains msg if {
  not input.asset.baseline_id
  msg := "{{controlId}}: asset missing approved baseline"
}

deny contains msg if {
  input.asset.drift_count > 0
  not input.asset.approved_exception
  msg := "{{controlId}}: unapproved configuration drift detected"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.auth.unique_identity
  input.auth.mfa_satisfied
  input.auth.session_bound
}

deny contains msg if {
  not input.auth.unique_identity
  msg := "{{controlId}}: authentication is not bound to a unique identity"
}

deny contains msg if {
  input.auth.unique_identity
  not input.auth.mfa_satisfied
  msg := "{{controlId}}: multi-factor authentication was not satisfied"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.boundary.managed_interface
  input.boundary.default_deny
  input.boundary.flow_approved
  input.boundary.flow_logged
}

deny contains msg if {
  not input.boundary.managed_interface
  msg := "{{controlId}}: traffic does not traverse a managed interface"
}

deny contains msg if {
  input.boundary.managed_interface
  not input.boundary.default_deny
  msg := "{{controlId}}: boundary lacks a default-deny posture"
}

deny contains msg if {
  input.boundary.managed_interface
  not input.boundary.flow_approved
  msg := "{{controlId}}: communication flow is not approved"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.audit.events_defined
  input.audit.records_generated
  input.audit.content_complete
}

deny contains msg if {
  not input.audit.events_defined
  msg := "{{controlId}}: auditable events are not defined"
}

deny contains msg if {
  input.audit.events_defined
  not input.audit.records_generated
  msg := "{{controlId}}: audit records are not generated for defined events"
}

deny contains msg if {
  input.audit.records_generated
  not input.audit.content_complete
  msg := "{{controlId}}: audit record content is incomplete for investigation"
}

package {{packageName}}

import rego.v1

default allow := false

allow if {
  input.finding.tracked
  input.finding.severity == "critical"
  input.finding.age_days <= 15
}

allow if {
  input.finding.tracked
  input.finding.severity == "critical"
  input.finding.approved_exception
}

allow if {
  input.finding.tracked
  input.finding.severity != "critical"
  input.finding.age_days <= 30
  input.finding.remediated
}

deny contains msg if {
  not input.finding.tracked
  msg := "{{controlId}}: vulnerability finding is not tracked"
}

deny contains msg if {
  input.finding.severity == "critical"
  input.finding.age_days > 15
  not input.finding.remediated
  not input.finding.approved_exception
  msg := "{{controlId}}: critical flaw exceeded remediation SLA"
}
